set -euo pipefail
ssh -o BatchMode=yes -o ConnectTimeout=10 michal@192.168.0.23 'bash -s' <<'REMOTE'
set -eu
pid=$(pgrep -f '[p]ython.*server.py' | head -n 1 || true)
if [ -z "$pid" ]; then echo 'PhotoMap server process not found'; exit 2; fi
cwd=$(readlink -f "/proc/$pid/cwd")
exe=$(readlink -f "/proc/$pid/exe")
PID="$pid" CWD="$cwd" "$exe" - <<'PY'
import os
import sqlite3
from collections import Counter
from pathlib import Path

pid = os.environ['PID']
cwd = Path(os.environ['CWD'])
proc_env = {}
for item in Path(f'/proc/{pid}/environ').read_bytes().split(b'\0'):
    if b'=' in item:
        key, value = item.split(b'=', 1)
        proc_env[key.decode(errors='replace')] = value.decode(errors='replace')
backend = cwd / 'backend'
storage = Path(proc_env.get('PHOTOMAP_STORAGE_DIR', str(backend / 'storage'))).expanduser()
data = Path(proc_env.get('PHOTOMAP_DATA_DIR', str(backend / 'data'))).expanduser()
db_url = proc_env.get('DATABASE_URL', f'sqlite:///{data / "app.db"}')
if not db_url.startswith('sqlite:///'):
    raise SystemExit('Expected sqlite database')
db = Path(db_url.removeprefix('sqlite:///'))
if not db.is_absolute(): db = (cwd / db).resolve()

def human(n):
    value=float(n)
    for unit in ('B','KiB','MiB','GiB','TiB'):
        if value < 1024 or unit == 'TiB': return f'{value:.2f} {unit}'
        value/=1024

conn = sqlite3.connect(f'file:{db}?mode=ro', uri=True)
conn.row_factory = sqlite3.Row
try:
    photos = conn.execute('SELECT id, place_id, original_path, public_path, thumb_path, audio_original_path, audio_public_path, attribution_source_url FROM photo').fetchall()
    places = {row['id']: row['title'] for row in conn.execute('SELECT id, title FROM place')}
finally:
    conn.close()

private_refs=set(); public_refs=set()
for row in photos:
    if row['original_path']: private_refs.add((storage/'private'/row['original_path']).resolve())
    if row['audio_original_path']: private_refs.add((storage/'private'/row['audio_original_path']).resolve())
    if row['public_path']: public_refs.add((storage/'public'/row['public_path'].removeprefix('/media/')).resolve())
    if row['thumb_path']: public_refs.add((storage/'public'/row['thumb_path'].removeprefix('/media/')).resolve())
    if row['audio_public_path']: public_refs.add((storage/'public'/row['audio_public_path'].removeprefix('/media/')).resolve())

def unreferenced(root, refs):
    result=[]
    if root.exists():
        for p in root.rglob('*'):
            if p.is_file() and p.resolve() not in refs:
                result.append((p.stat().st_size,p))
    return sorted(result, key=lambda x:(-x[0],str(x[1])))

private_unreferenced=unreferenced(storage/'private',private_refs)
public_unreferenced=unreferenced(storage/'public',public_refs)
print('=== TRUE UNREFERENCED STORAGE ===')
for label,items in [('private',private_unreferenced),('public',public_unreferenced)]:
    total=sum(size for size,_ in items)
    print(f'{label}_unreferenced_files={len(items)} bytes={total} ({human(total)})')
    for size,path in items[:30]: print(f'  bytes={size} ({human(size)}) path={path}')

source_groups={}
for row in photos:
    url=row['attribution_source_url']
    if url: source_groups.setdefault(url,[]).append(row)
print('=== DUPLICATED SOURCE URL PLACE MAPPING ===')
for url,items in sorted(source_groups.items()):
    if len(items)<=1: continue
    print(f'url={url} count={len(items)}')
    for row in items:
        print(f'  photo_id={row["id"]} place_id={row["place_id"]} place_title={places.get(row["place_id"],"<missing>")}')
